    #[test]
    fn case_d_package_with_no_collision_stays_bare() {
        let dir = tempfile::tempdir().expect("tempdir");
        let root = dir.path();
        write_pkg(root, "crates/foo", Ecosystem::Cargo, "foo");
        std::fs::write(
            root.join("crates/foo/package.json"),
            r#"{"name":"@myorg/foo","version":"0.1.0"}"#,
        )
