        assert_eq!(
            pcfg.release_trigger,
            Some(ReleaseTrigger::Auto),
            "npm/foo (declared first) must win over cargo/foo (declared second) — Vec order, \
             not alphabetical sort, governs first-match-wins (AC-F5). \
