                assert_eq!(group.as_str(), "linked-a");
                assert_eq!(other.as_str(), "fixed-a");
                assert_eq!(member, "shared");
            }
            other => panic!("expected ConflictingGroupNames, got {other:?}"),
        }
    }
}

